"""Write Sources/PulseCore/BoardRecipeData.swift from fit.py's recipes.json.

    python3 gen_swift.py recipes.json ../../Sources/PulseCore/BoardRecipeData.swift
"""
import json, sys
from fit import BANDS, TIMES, FLOOR

recipes = json.load(open(sys.argv[1]))
names = {'thingy': 'creamy', 'rainy': 'velvet', 'orange': 'citrus', 'keychron': 'alloy', 'apex': 'crisp'}
groups = ['text', 'space', 'returnKey', 'delete', 'navigation', 'modifier']
lines = [
    '// Generated by scripts/boards/gen_swift.py. Do not edit by hand.',
    '//',
    "// Each board is a measured description of a keyboard's sound, never the sound",
    '// itself: for every key group, the level (dB) of 21 third-octave noise bands',
    f'// at 17 moments in the first 140 ms, rounded to whole decibels and stored as',
    f'// hex bytes (dB + {-FLOOR}; 00 is silence). SoundSynth renders it from fresh noise.',
    '',
    'extension BoardRecipes {',
    '    static let bands: [Double] = [' + ', '.join(f'{b:.1f}' for b in BANDS) + ']',
    '    static let times: [Double] = [' + ', '.join(f'{t / 1000:.3f}' for t in TIMES) + ']',
    '',
    '    static let table: [KeyboardBoard: [KeyGroup: Encoded]] = [',
]
for source, board in names.items():
    lines.append(f'        .{board}: [')
    for g in groups:
        e = recipes[source][g]
        hexed = ''.join(f'{max(0, min(255, v - FLOOR)):02x}' for row in e['db'] for v in row)
        lines.append(f'            .{g}: Encoded(levels: "{hexed}", length: {e["length_ms"] / 1000:.3f}, loudness: {e["loudness_db"]}, width: {e["width"]}),')
    lines.append('        ],')
lines += ['    ]', '}']
open(sys.argv[2], 'w').write('\n'.join(lines) + '\n')
print('wrote', sys.argv[2])
